$string['app_rm_warning'] = 'Wer diese Adresse hat, kann Ihre Tafel steuern, solange sie geöffnet ist, sieht aber nichts von den Teilnehmern. Wenn Sie sie versehentlich weitergegeben haben, ändern Sie sie.';
$string['app_sh_shared'] = 'Mit der Schule geteilt: Jetzt können alle Trainer es verwenden.';
$string['app_wb_send_note'] = 'Sie wird im Kurs im Abschnitt „Klassentafeln“ in einem Ordner für diese Klasse gespeichert, und die Teilnehmer erhalten eine Benachrichtigung.';
$string['app_wb_send_note_cohort'] = 'Diese Klasse ist keine Moodle-Gruppe: Alle im Kurs können ihren Ordner sehen; nur ihre Teilnehmer erhalten die Benachrichtigung.';
$string['choose_desc'] = 'Wählen Sie einen Kurs, und die Werkzeuge öffnen sich mit seinen bereits geladenen Teilnehmern.';
