$string['days_desc'] = 'Beim Auswählen kommen Teilnehmer, die in diesen letzten Tagen am wenigsten ausgewählt wurden, zuerst. Es ist auch der Zeitraum, der unter „Beteiligung“ angezeigt wird.';
$string['helpurl_desc'] = 'Die Adresse, die der letzte Schritt der Tour für Trainer öffnet: ein Video oder eine Anleitung Ihrer Schule. Leer: die offizielle Seite von Classtools mit ihrem Video, in der Sprache des/der jeweiligen Trainer/in.';
$string['levels_desc'] = 'Der Inhalt der Spiele (eingebaute Sets: Formen, Tierschatten, Einmaleins, chemische Elemente, Funktionsgraphen …) für die an dieser Schule unterrichteten Stufen. Es lassen sich mehrere ankreuzen, und Trainer können sie in jedem Spiel weiter eingrenzen. Das ist getrennt vom Bildschirmmodus oben, von dem immer nur einer gilt.';
$string['live_desc'] = 'Die Tafel kann Live-Sitzungen öffnen: Teilnehmer beantworten eine Abstimmung oder drücken den Buzzer ihres Teams von einem Tablet, einem Chromebook oder einem Handy aus, und der/die Trainer/in kann das eigene Handy als Fernbedienung für die Tafel nutzen. Jede Sitzung wird auf einem von zwei Wegen geöffnet: mit dem Code auf der Tafel (niemand meldet sich an, und es erscheinen keine Namen) oder mit den Moodle-Konten der Teilnehmer (nur Teilnehmer des Kurses, mit ihren Namen). Solange eine Sitzung offen ist, fragt jedes Gerät alle anderthalb Sekunden bei der Website nach dem Stand; Sitzungen enden von selbst nach 15 Minuten ohne die Tafel und werden am nächsten Tag gelöscht.';
$string['livenotice'] = 'Hinweis für Teilnehmer';
$string['livenotice_desc'] = 'Wenn ein/e Trainer/in eine Live-Sitzung öffnet, sehen die Teilnehmer dieses Kurses auf den Kursseiten einen kleinen Hinweis mit einer Taste zum Beitreten: Sie müssen weder den Code eintippen noch den QR-Code scannen.';
$string['logros'] = 'Sticker der Trainer';
$string['logros_desc'] = 'Jedes Werkzeug hat einen Sticker für den/die Trainer/in, den man erhält, wenn man es wirklich mit einer Klasse nutzt, und der mit den Tagen der Nutzung eine Stufe aufsteigt (1, 3, 8, 20 und 50). Jede/r Trainer/in sieht nur das eigene Album, unter „Welche Klasse?“; es gibt nie eine Rangfolge unter den Trainern.';
$string['logros_picks_desc'] = 'Wie viele Teilnehmer am selben Tag in derselben Klasse ausgewählt werden müssen.';
$string['logros_students'] = 'Teilnehmer für echte Gruppen';
$string['logros_students_desc'] = 'Wie viele Teilnehmer die Kursliste haben muss, wenn damit Gruppen gebildet werden.';
$string['oksigeniaclasstools:manageshared'] = 'Entfernen, was Trainer mit der Schule teilen';
$string['oksigeniaclasstools:use'] = 'Die Klassenzimmer-Werkzeuge mit den Teilnehmern des Kurses nutzen';
$string['privacy:metadata:core_message'] = 'Teilnehmer erhalten eine Benachrichtigung, wenn ein/e Trainer/in eine Zeichentafel mit ihrer Klasse teilt.';
$string['privacy:metadata:live'] = 'Von Trainern auf der Tafel geöffnete Live-Sitzungen.';
$string['privacy:metadata:remote'] = 'Die feste Fernbedienung der einzelnen Trainer: eine Adresse für ihr Handy mit einem Schlüssel und die Angabe, ob sie eingeschaltet ist.';
$string['privacy:metadata:shared'] = 'Die Klassenlisten, Buchstabenräder und Schlösser, die ein/e Trainer/in mit der ganzen Website teilt, damit alle Trainer sie verwenden können.';
$string['privacy:metadata:uses'] = 'Die echten Nutzungen der Werkzeuge mit einer Klasse, gespeichert für die Sticker der Trainer: eine pro Sticker, Kurs und Tag.';
$string['remoteoff_desc'] = 'Die feste Fernbedienung der einzelnen Trainer schaltet sich nach diesen Stunden ohne Befehle vom Handy von selbst aus (gerechnet ab dem Einschalten). Der/Die Trainer/in schaltet sie auf der Tafel mit einem Tipp wieder ein.';
$string['sala_desc'] = 'Unter „Welche Klasse?“ erscheinen die Trainer, die dort auftauchen möchten, mit ihrem Tierchen und ihren Stickern, damit alle wissen, wer sonst noch mit seiner Klasse spielt. Jede/r Trainer/in entscheidet selbst, ob er/sie erscheint (zu Beginn nicht), und kann jederzeit wieder gehen. Zahlen und Stunden werden nie gezeigt, und niemand wird nach Nutzung sortiert. Es setzt eingeschaltete Sticker voraus.';
$string['shared_desc'] = 'Trainer können ihre von Hand eingefügten Klassenlisten, ihre Buchstabenräder und ihre Schlösser mit allen Trainern der Website teilen. Diese sehen sie in denselben Listen wie ihre eigenen und können sie verwenden oder kopieren, um sie zu ändern. Wer etwas geteilt hat, kann das Teilen beenden, und Manager können alles entfernen (Fähigkeit local/oksigeniaclasstools:manageshared).';
$string['show_tools_desc'] = 'Die Reiter, die die Tafel auf dieser Website zeigt. Lassen Sie die weg, die Ihre Schule nicht nutzt: Trainer sehen sie dann nicht.';
$string['students'] = 'Die Tafel für Teilnehmer öffnen';
$string['students_desc'] = 'Teilnehmer erhalten in jedem Kurs einen Link zur Tafel, nur mit den Werkzeugen, die keine Daten der Klasse nutzen: die Spiele (Simon, Tangram, Stäbe …), die Zeichentafel, der Timer, die Stoppuhr, die Uhr und der QR-Code. Die Teilnehmer sehen nie Namenslisten, Fotos, Auswahlen oder Gruppen, und nichts von ihnen wird in Moodle gespeichert. Ist es ausgeschaltet, sehen nur Trainer die Werkzeuge.';
$string['tourdescription'] = 'Zeigt Trainern, wo die Klassenzimmer-Werkzeuge sind.';
$string['tourstep1content'] = '<p>Für den Klassenbildschirm, mit den Teilnehmern dieses Kurses und ihren Fotos: wer dran ist, zufällige Gruppen, eine Anzeigetafel, Spiele für die ganze Klasse, Cuisenaire-Stäbe und ein Tangram, ein Lärmmesser, ein Timer und mehr.</p>';
$string['usage_desc'] = 'Wie oft jedes Werkzeug, Spiel und Material der Tafel ausgewählt wurde und wie lange es in Gebrauch war (solange die Tafel auf dem Bildschirm war und in den letzten 15 Minuten jemand sie berührt hatte), auf den Tafeln der Teilnehmer und der Trainer. Das von Teilnehmern am meisten genutzte zuerst.';
$string['usage_see'] = 'Sehen Sie, wofür die Tafeln genutzt werden: Werkzeuge, Spiele und Materialien, von Teilnehmern und von Trainern.';
$string['usage_students_opens'] = 'Teilnehmer: Anzahl';
$string['usage_students_time'] = 'Teilnehmer: Zeit';
$string['usage_teachers_opens'] = 'Trainer: Anzahl';
$string['usage_teachers_time'] = 'Trainer: Zeit';
